const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const main=$('#main'), dialog=$('#spec-dialog');
let pack='E',page='home',family=2,step=0,done=false,dropStep=0,cut=false,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,scrollSync=true;
let stopHeroBloom=()=>{};
const draft={family:'Dropout — air comprimé',application:'',pressure:'',flow:'',unknown:false,name:'',company:'',email:''};
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(id,alt,cls='',lazy=false)=>{const a=IMAGE_ASSETS[id];return `<img class="${cls}" src="${a.src}" alt="${escapeHTML(a.title)} — photo d’illustration" width="${a.width}" height="${a.height}" ${lazy?'loading="lazy"':''} decoding="async">`};
const dropoutImage=(cls='',lazy=false)=>`<img class="${cls}" src="assets/dropout-cutout.png" width="455" height="1738" alt="Séparateur Dropout, corps en aluminium et raccords bleus — visuel fourni amélioré" ${lazy?'loading="lazy"':''} decoding="async">`;
const primary=(text,attrs)=>`<button class="button primary" ${attrs}>${text}<span aria-hidden="true">↗</span></button>`;
const textButton=(text,attrs)=>`<button class="text-button" ${attrs}>${text}<span aria-hidden="true">↗</span></button>`;
const eyebrow=t=>`<div class="eyebrow"><span></span>${t}</div>`;
function familyTabs(){return `<div class="family-tabs" role="group" aria-label="Grandeur physique">${FAMILIES.map((f,i)=>`<button data-family="${i}" aria-pressed="${i===family}"><span class="mono">${f.code}</span>${f.name}<span class="tab-marker" aria-hidden="true">↗</span></button>`).join('')}</div>`}
function specimen(){const f=FAMILIES[family];return `<div class="specimen-meta"><span class="mono">${f.code} / ${f.name.toUpperCase()}</span><span class="mono">UNITÉ / ${f.unit}</span></div>${img(f.img,'Exemple d’instrument de '+f.name.toLowerCase(),'hero-key-image')}<div class="specimen-caption"><span>${f.use}</span><span class="mono">MATURAT / MESURE</span></div>`}
function instrumentCollage(){return `<div class="instrument-collage" data-art><div class="ambient" aria-hidden="true"></div>${img(270,'Instrument de pression','object object-pressure')}${img(238,'Sondes de température','object object-temp')}${img(202,'Instrument de niveau','object object-level')}<span class="object-label label-p mono">03 / PRESSION</span><span class="object-label label-t mono">02 / TEMPÉRATURE</span><span class="object-label label-l mono">01 / NIVEAU</span><span class="collage-foot mono">Manomètre : Photo by CEphoto, Uwe Aranas<br>CC BY-SA 3.0 · Visuels d’illustration</span></div>`}
function home(){const p=PACKS[pack];let hero='';const intro=`<p class="hero-intro">Instrumentation et solutions de contrôle pour vos procédés industriels. Définissons ensemble la solution adaptée à votre application.</p>`;
if(pack==='A')hero=`<section class="hero hero-signal"><div class="hero-copy">${eyebrow('INSTRUMENTATION INDUSTRIELLE')}<h1>${p.heading}</h1>${intro}${primary('Explorer les solutions','data-scroll="solutions"')}</div><div class="signal-right"><div class="specimen" id="hero-specimen" data-art>${specimen()}</div>${familyTabs()}</div><div class="hero-foot"><span class="mono">NIVEAU / TEMPÉRATURE / PRESSION / DÉBIT</span><span class="mono">01 — L’EXPERTISE MATURAT</span></div></section>`;
if(pack==='B')hero=`<section class="hero hero-noir"><div class="noir-beam" aria-hidden="true"></div><div class="hero-copy">${eyebrow('MESURE / CONTRÔLE / FLUIDES')}<h1>${p.heading}</h1>${intro}${primary('Explorer les solutions','data-scroll="solutions"')}</div>${instrumentCollage()}<div class="hero-foot"><span class="mono">L’INGÉNIERIE SE RÉVÈLE</span>${textButton('Découvrir Dropout','data-page="dropout"')}</div></section>`;
if(pack==='C')hero=`<section class="hero hero-editorial">${eyebrow('MATURAT MESURE — INSTRUMENTATION INDUSTRIELLE')}<h1>${p.heading}</h1><div class="editorial-caption"><span class="mono">LA MESURE,<br>AU PLUS PRÈS<br>DE VOTRE PROCÉDÉ.</span></div><div class="editorial-intro">${intro}${textButton('Explorer les solutions','data-scroll="solutions"')}</div><div class="editorial-object" data-art>${img(270,'Instrument de pression')}<span class="mono">FIG. 01 — MESURE DE PRESSION</span></div><div class="hero-foot"><span class="mono">NIVEAU · TEMPÉRATURE · PRESSION · DÉBIT</span><span class="mono">SCROLL POUR EXPLORER ↓</span></div></section>`;
if(pack==='D')hero=`<section class="hero hero-control"><div class="hero-copy">${eyebrow('INSTRUMENTATION / SÉLECTION')}<h1>${p.heading}</h1>${intro}<p class="mono control-prompt">SÉLECTIONNER UNE GRANDEUR ↓</p>${familyTabs()}</div><div class="control-panel"><div class="control-top"><span class="mono">EXPLORATEUR D’INSTRUMENTS</span><span class="mono">01 — 04</span></div><div class="specimen" id="hero-specimen" data-art>${specimen()}</div><div class="control-principles" id="control-principles">${principles()}</div></div></section>`;
if(pack==='E')hero=`<section class="hero hero-focus" aria-labelledby="hero-title"><div class="hero-focus-atmosphere" aria-hidden="true"><img class="hero-focus-texture" src="assets/hero-blue-grain.png" width="1774" height="887" alt="" fetchpriority="high" decoding="async"><div class="hero-bloom-mesh"></div></div><div class="hero-focus-stage" data-art><figure class="hero-focus-product">${dropoutImage('hero-focus-equipment').replace('<img ', '<img fetchpriority="high" ')}<figcaption>Dropout <span>Traitement de l’air comprimé</span></figcaption></figure></div><div class="hero-focus-bottom"><h1 id="hero-title">${p.heading}</h1><div class="hero-focus-intro">${intro}${textButton('Explorer les solutions','data-scroll="solutions"')}</div></div></section>`;
return hero+solutions()+feature();}
function principles(){return `<span class="mono">PRINCIPES DE MESURE</span><p>${FAMILIES[family].principles.join(' · ')}</p>`}
function solutions(){return `<section class="solutions solutions-catalog section" id="solutions"><div class="section-heading"><div><h2>Tout commence<br><em>par la bonne mesure.</em></h2><p>Quatre grandeurs fondamentales.<br>Une sélection guidée par vos contraintes.</p></div></div><div class="family-grid">${FAMILIES.map((f,i)=>`<button class="family-card measure-card measure-${f.code}" data-family="${i}" aria-pressed="${family===i}" style="--family-halo:${f.color}"><div class="measure-copy"><span class="mono">${f.code}</span><h3>${f.name}</h3><p>${f.text}</p></div>${img(f.img,'Exemple d’instrument de '+f.name.toLowerCase(),'measure-image',true)}<span class="measure-arrow" aria-hidden="true">↗</span>${f.img===270?'<span class="measure-credit">Photo by CEphoto, Uwe Aranas · CC BY-SA 3.0</span>':''}</button>`).join('')}</div><div class="family-inspector" id="family-inspector" aria-live="polite">${inspector()}</div></section>`}

function inspector(){const f=FAMILIES[family];return `<div><span class="mono">${f.code} / ${f.name.toUpperCase()}</span><h3>${f.title}</h3></div><div><p>${f.text}</p><div class="principles">${f.principles.map(x=>`<span>${x}</span>`).join('')}</div></div>${textButton('Définir mon besoin',`data-need="${f.name}"`)}`}
function feature(){return `<section class="drop-feature" data-feature><div class="feature-wash" aria-hidden="true"></div><div class="feature-copy"><h2>Moins de condensats.<br><em>Plus de maîtrise.</em></h2><p>Découvrez Dropout, une technologie de séparation pour préserver vos équipements alimentés en air comprimé.</p>${primary('Découvrir Dropout','data-page="dropout"')}<div class="feature-benefits"><span>Sans alimentation électrique</span><span>Sans consommable</span></div></div><div class="feature-object" data-art>${dropoutImage('feature-dropout',true)}<span class="mono">DROP’OUT / TECHNOLOGIE DE SÉPARATION</span></div></section>`}
function stageTabs(){return `<div class="stage-tabs" role="group" aria-label="Étapes du fonctionnement">${DROP_STEPS.map((s,i)=>`<button data-stage="${i}" aria-pressed="${i===dropStep}"><span class="mono">0${i+1}</span>${s.name}</button>`).join('')}</div>`}
function flowDiagram(){return `<div class="flow-diagram" role="group" aria-label="Schéma pédagogique simplifié du flux"><svg class="flow-connectors" viewBox="0 0 440 360" aria-hidden="true"><defs><marker id="flow-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10Z" fill="#4395d1"/></marker><marker id="purge-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10Z" fill="#f7941d"/></marker></defs><path class="air-path" d="M85 135 H159 M281 135 H353"/><path class="purge-path" d="M220 177 V252"/></svg><button class="flow-node flow-in" data-stage="0" aria-pressed="${dropStep===0}"><span>01</span>Air entrant</button><button class="flow-node flow-separation" data-stage="1" aria-pressed="${dropStep===1}"><span>02</span>Séparation</button><button class="flow-node flow-out" data-stage="3" aria-pressed="${dropStep===3}"><span>04</span>Flux en sortie</button><button class="flow-node flow-purge" data-stage="2" aria-pressed="${dropStep===2}"><span>03</span>Collecte & purge</button><span class="flow-note">Schéma de principe simplifié<br>Sans représentation de la construction interne</span></div>`}
function productStage(){return `<div class="product-stage ${cut?'is-cut':''}" data-active="${dropStep}"><div class="stage-ambient" aria-hidden="true"></div><span class="mono stage-id">${cut?'PRINCIPE DE SÉPARATION':'SÉPARATEUR DROPOUT'}</span><div class="product-frame">${dropoutImage('drop-whole').replace('<img ',`<img aria-hidden="${cut}" `)}<div class="drop-cut" aria-hidden="${!cut}" ${cut?'':'inert'}>${flowDiagram()}</div></div><div class="view-switch" role="group" aria-label="Présentation"><button data-cut="false" aria-pressed="${!cut}">Équipement</button><button data-cut="true" aria-pressed="${cut}">Schéma du flux</button></div><span class="image-source">Visuel fourni · Détourage et netteté améliorés pour la maquette</span></div>`}
function dropCopy(){const s=DROP_STEPS[dropStep];return `<span class="mono">0${dropStep+1} / ${s.name.toUpperCase()}</span><h2>${s.title}</h2><p>${s.text}</p>`}
function dropout(){const cinematic=pack==='B'||pack==='E';return `<section class="drop-intro"><button class="back" data-page="home">← Nos solutions</button><div class="drop-intro-grid"><div>${eyebrow('TRAITEMENT DE L’AIR COMPRIMÉ')}<h1>Drop’out.</h1><h2>Protéger ce qui fait<br>avancer vos procédés.</h2></div><div><p>Une technologie de séparation des liquides et particules, pour préserver vos organes pneumatiques et vos instruments.</p><div class="intro-actions">${primary('Étudier mon application','data-need="Dropout — air comprimé"')}${textButton('Explorer le fonctionnement','data-scroll="fonctionnement"')}</div></div></div></section><section class="drop-experience ${cinematic?'cinematic':''}" id="fonctionnement"><div class="drop-sticky"><div class="drop-workspace"><div class="drop-stage-shell">${productStage()}</div><div class="drop-editorial">${eyebrow('COMPRENDRE LE PRINCIPE')}<div class="drop-copy" aria-live="polite">${dropCopy()}</div>${stageTabs()}${cinematic?`<button class="sync-button" aria-pressed="${scrollSync}" data-sync>Progression au scroll : ${scrollSync?'activée':'en pause'}</button>`:''}<p class="small-note">Choisissez une étape ou explorez le schéma du flux.</p></div></div>${cinematic?'<div class="scroll-track" aria-hidden="true"><span></span></div>':''}</div></section><section class="application-cta section"><div>${eyebrow('LE BON MODÈLE POUR VOTRE INSTALLATION')}<h2>Votre procédé<br>a ses particularités.</h2></div><div><p>Fluide, pression, débit et contraintes d’installation : ces éléments permettent de préparer le dimensionnement.</p><p class="small-note">Les performances doivent être confirmées pour l’application retenue. La maquette ne réalise aucun calcul de dimensionnement.</p>${primary('Définir mon besoin','data-need="Dropout — air comprimé"')}</div></section>`}
function familyOptions(){return ['Dropout — air comprimé',...FAMILIES.map(f=>f.name),'Autre / à préciser'].map(v=>`<option ${draft.family===v?'selected':''}>${v}</option>`).join('')}
function summary(compact=false){const data=[['Besoin',draft.family],['Application',draft.application||'À préciser'],['Pression',draft.unknown?'À définir':draft.pressure?draft.pressure+' bar':'Non renseignée'],['Débit',draft.unknown?'À définir':draft.flow?draft.flow+' m³/h':'Non renseigné']];if(!compact)data.push(['Contact',draft.name],['Entreprise',draft.company||'Non renseignée'],['E-mail',draft.email]);return `<dl class="summary">${data.map(([k,v])=>`<div><dt>${k}</dt><dd>${escapeHTML(v)}</dd></div>`).join('')}</dl>`}
function fields(){if(done)return `<div class="form-success" role="status"><span class="success-mark" aria-hidden="true">✓</span><span class="mono">DÉMONSTRATION TERMINÉE</span><h2>Le premier pas<br>est fait.</h2><p>Votre parcours est terminé. Aucune demande n’a été envoyée à Maturat.</p><p class="small-note">Recommencez avec une nouvelle application pour explorer un autre besoin.</p>${primary('Recommencer','type="button" data-reset')}</div>`;
if(step===0)return `<span class="mono form-kicker">01 / VOTRE BESOIN</span><h2>Parlons de votre application.</h2><p class="form-intro">Quelques mots suffisent pour commencer.</p><label for="family">Votre besoin</label><select name="family" id="family">${familyOptions()}</select><label for="application">Que souhaitez-vous mesurer ou protéger ? <span>*</span></label><textarea id="application" name="application" required maxlength="1800" placeholder="Ex. : protéger les instruments de notre réseau d’air comprimé…">${escapeHTML(draft.application)}</textarea><fieldset><legend>Paramètres connus <span>(facultatif)</span></legend><div class="parameter-fields"><div><label for="pressure">Pression</label><div class="unit-input"><input id="pressure" name="pressure" type="number" inputmode="decimal" min="0" step="any" value="${escapeHTML(draft.pressure)}" ${draft.unknown?'disabled':''} placeholder="7"><span>bar</span></div></div><div><label for="flow">Débit</label><div class="unit-input"><input id="flow" name="flow" type="number" inputmode="decimal" min="0" step="any" value="${escapeHTML(draft.flow)}" ${draft.unknown?'disabled':''} placeholder="À préciser"><span>m³/h</span></div></div></div><label class="check"><input type="checkbox" name="unknown" ${draft.unknown?'checked':''}>Je ne connais pas encore ces valeurs</label></fieldset><div class="form-actions"><span class="small-note">* Champ requis</span>${primary('Continuer','type="submit"')}</div>`;
if(step===1)return `<span class="mono form-kicker">02 / VOTRE CONTACT</span><h2>Faisons connaissance.</h2><p class="form-intro">Utilisez des coordonnées fictives pour tester ce parcours.</p><label for="name">Prénom et nom <span>*</span></label><input id="name" name="name" required maxlength="120" autocomplete="name" value="${escapeHTML(draft.name)}" placeholder="Camille Martin"><label for="company">Entreprise <span>(facultatif)</span></label><input id="company" name="company" maxlength="150" autocomplete="organization" value="${escapeHTML(draft.company)}" placeholder="Votre entreprise"><label for="email">Adresse e-mail professionnelle <span>*</span></label><input id="email" name="email" type="email" required maxlength="200" autocomplete="email" value="${escapeHTML(draft.email)}" placeholder="camille@example.com"><div class="form-actions"><button type="button" data-prev>← Retour</button>${primary('Vérifier la demande','type="submit"')}</div>`;
return `<span class="mono form-kicker">03 / VOTRE RÉSUMÉ</span><h2>Votre demande, en clair.</h2>${summary()}<p class="small-note">Cette démonstration ne transmet aucune information à Maturat.</p><div class="form-actions"><button type="button" data-prev>← Modifier</button>${primary('Simuler la demande','type="submit"')}</div>`}
function quote(){return `<section class="quote-page"><div class="quote-heading"><button class="back" data-page="home">← Nos solutions</button>${eyebrow('DÉFINIR VOTRE BESOIN')}<h1>Une solution juste.<br><em>Commençons par vous.</em></h1><p>Votre application est le point de départ.<br>Préparons un échange avec Maturat Mesure.</p></div><div class="quote-layout"><aside class="quote-aside"><ol class="form-progress">${['Besoin','Contact','Résumé'].map((s,i)=>`<li ${step===i?'aria-current="step"':''} class="${step>=i?'visited':''}"><span>0${i+1}</span>${s}${step>i?'<b aria-hidden="true">✓</b>':''}</li>`).join('')}</ol><div class="side-summary"><span class="mono">VOTRE APPLICATION</span><div id="live-summary">${summary(true)}</div></div><p class="privacy-note">Mode démonstration. Vos saisies restent dans cette page jusqu’à son rechargement. Aucun envoi réel.</p></aside><form class="form-card">${fields()}</form></div></section>`}
function footer(){return `<div class="footer-heading"><h2>La précision commence<br><em>par un échange.</em></h2>${textButton('Parlons de votre application','data-page="quote"')}</div><div class="footer-bottom"><a class="brand" href="#${pack}/home"><img src="assets/maturat-logo.png" alt="Maturat Mesure"></a><div><span>00 00 00 00 00</span><a href="mailto:contact@example.com">contact@example.com</a></div><div class="footer-address"><span class="mono footer-location">MATURAT MESURE / VILLE EXEMPLE, FRANCE</span>1 rue de la Démonstration<br>Ville exemple</div></div><div class="footer-meta"><span>Exploration de design · ${PACKS[pack].name}</span><span>Sources des visuels dans « Direction & crédits »</span><button data-open-spec>Direction & crédits ↗</button></div>`}
function photoCredits(){return `<section class="photo-credits"><span class="mono">PHOTOGRAPHIES / SOURCES & LICENCES</span><h2>Des visuels pour se projeter.</h2><p>Le visuel Dropout provient de l’extrait de plaquette fourni. Sa netteté a été améliorée avec l’IA, puis le fond a été retiré par détourage classique pour cette maquette. Les quatre photographies de catégories ci-dessous sont des illustrations sous licence Creative Commons, conservées sans retouche.</p><div class="credit-list">${Object.entries(IMAGE_ASSETS).filter(([id])=>id!=='132').map(([,a])=>`<article><img src="${a.src}" width="80" height="76" alt="" loading="lazy"><div><h3>${a.title}</h3><p>${a.author} · ${a.width.toLocaleString('fr-FR')} × ${a.height.toLocaleString('fr-FR')} px</p><div class="credit-links"><a href="${a.source}" target="_blank" rel="noopener noreferrer">Voir la source ↗</a><a href="${a.licenseUrl}" target="_blank" rel="noopener noreferrer">${a.license} ↗</a></div></div></article>`).join('')}</div></section>`}
function specContent(){const p=PACKS[pack];return `<div class="spec-heading"><span class="spec-letter">${pack}</span><div><p class="mono">${p.mood}</p><h1 id="spec-title">${p.name}</h1><p>${p.desc}</p></div></div><div class="swatch-grid">${p.palette.map(([name,hex])=>`<div class="swatch"><div style="background:${hex}"></div><strong>${name}</strong><code>${hex}</code></div>`).join('')}</div><div class="spec-grid"><section><span class="mono">TYPOGRAPHIE</span><div class="type-display">La précision,<br><em>en mouvement.</em></div><dl class="type-list"><div><dt>Titres</dt><dd>${p.fonts[0]}</dd></div><div><dt>Texte & interface</dt><dd>${p.fonts[1]}</dd></div><div><dt>Chiffres & unités</dt><dd>${p.fonts[2]}</dd></div></dl><div class="type-data">04.20 <small>mA</small> / 16 <small>bar</small></div><p class="small-note">Spécimen typographique : valeurs illustratives.</p></section><section><span class="mono">COMPOSITION & INTERACTIONS</span><h2>${p.tag}</h2><p>${p.composition}</p><p><strong>Mouvement.</strong> ${p.motion}</p><p><strong>Curseur.</strong> ${p.cursor}</p><div class="spec-tokens"><span>Arrondis <b>${p.radius}</b></span><span>Texte <b>16–18 px</b></span><span>Boutons <b>48–52 px</b></span></div></section></div><section class="component-sample"><span class="mono">COMPOSANTS / ÉTATS À EXPLORER</span><div class="sample-row">${primary('Demande de chiffrage','data-spec-quote')}${textButton('Découvrir une solution','data-spec-home')}<span class="sample-tag">PRESSION / bar</span><button class="sample-choice" aria-pressed="false" data-sample-choice>Option de démonstration</button></div><label for="sample-field">Champ de démonstration</label><input id="sample-field" placeholder="Survolez ou utilisez Tab pour voir le focus"><p class="small-note">Interactions 180–260 ms · Entrées de section 500–700 ms · Réduction des animations disponible.</p></section><section class="references"><span class="mono">RÉFÉRENCES & INTENTIONS</span>${p.refs.map(k=>`<a href="${REFS[k].url}" target="_blank" rel="noopener noreferrer"><div><h3>${REFS[k].name}</h3><p>${REFS[k].use}</p></div><span aria-hidden="true">↗</span></a>`).join('')}</section>${photoCredits()}<p class="source-note">Synthèse des deux rapports fournis, de votre cadrage et de la plaquette Maturat. Couleurs relevées dans le logo de la plaquette : bleu #4395D1, orange #F7941D, graphite #231F20. Les halos en sont des déclinaisons éclaircies. Les photos servent à illustrer la composition et ne constituent pas un catalogue de produits Maturat. Le visuel Dropout fourni a été amélioré avec l’IA puis détouré ; il sert à prévisualiser le design. Le schéma présente uniquement le parcours simplifié du flux. Les références servent de points de comparaison.</p>`}
function saveDraft(){if(page!=='quote')return;$$('form [name]').forEach(el=>draft[el.name]=el.type==='checkbox'?el.checked:el.value)}
function render(){stopHeroBloom();document.body.dataset.pack=pack;document.body.dataset.page=page;document.body.classList.toggle('reduced',reduced);$('.pack-switch').innerHTML=Object.entries(PACKS).map(([k,p])=>`<button data-pack="${k}" aria-pressed="${pack===k}" aria-label="${k} — ${p.name}"><span class="pack-letter">${k}</span><span>${p.short}</span>${k==='E'?'<span class="pack-star" aria-label="Hybride">✳</span>':''}</button>`).join('');$('#motion').setAttribute('aria-pressed',reduced);$('#motion span').textContent=reduced?'réduit':'activé';$('.site-header .brand').href=`#${pack}/home`;$$('.site-header [data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page===page?'page':'false'));main.innerHTML=page==='home'?home():page==='dropout'?dropout():quote();$('#footer').innerHTML=footer();document.title=`${PACKS[pack].name} — ${page==='home'?'Accueil':page==='dropout'?'Dropout':'Votre besoin'} · Maturat`;if(dialog.open)$('#spec-content').innerHTML=specContent();setupReveal();stopHeroBloom=window.HeroBloom.mount($('.hero-focus-atmosphere'),reduced);}
function readRoute(){const [a,b]=(location.hash.slice(1)||'E/home').split('/');pack='E';page=['home','dropout','quote'].includes(b)?b:'home'}
function navigate(p){saveDraft();if(page===p){render();window.scrollTo({top:0,behavior:'instant'});return}location.hash=`${pack}/${p}`}
function focusForm(){const h=$('form h2');if(h){h.tabIndex=-1;h.focus({preventScroll:true});h.scrollIntoView({block:'nearest',behavior:'instant'})}}
function updateFamily(i){family=i;document.body.style.setProperty('--selected-halo',FAMILIES[i].color);$$('[data-family]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.family)===i));if($('#hero-specimen'))$('#hero-specimen').innerHTML=specimen();if($('#control-principles'))$('#control-principles').innerHTML=principles();if($('#family-inspector'))$('#family-inspector').innerHTML=inspector()}
function updateDrop(i,fromScroll=false){dropStep=i;if(!fromScroll){cut=true;scrollSync=false;const b=$('[data-sync]');if(b){b.textContent='Progression au scroll : en pause';b.setAttribute('aria-pressed','false')}}const stage=$('.product-stage');if(!stage)return;stage.dataset.active=i;stage.classList.toggle('is-cut',cut);$$('.hotspot').forEach(b=>b.disabled=!cut);$('.drop-whole').setAttribute('aria-hidden',cut);$('.drop-cut').setAttribute('aria-hidden',!cut);$('.stage-id').textContent=cut?'PRINCIPE DE SÉPARATION':'SÉPARATEUR DROPOUT';$('.drop-cut').inert=!cut;$$('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.stage)===i));$$('[data-cut]').forEach(b=>b.setAttribute('aria-pressed',(b.dataset.cut==='true')===cut));$('.drop-copy').innerHTML=dropCopy()}
let revealObserver;function setupReveal(){revealObserver?.disconnect();if(reduced)return;revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');revealObserver.unobserve(e.target)}}),{threshold:.08});$$('.section-heading,.family-card,.family-inspector,.feature-copy,.feature-object,.application-cta').forEach(el=>{el.classList.add('will-reveal');revealObserver.observe(el)})}
function openSpec(){saveDraft();$('#spec-content').innerHTML=specContent();dialog.showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.pack){saveDraft();const pos=window.scrollY;pack='E';history.replaceState(null,'',`#${pack}/${page}`);render();window.scrollTo({top:pos,behavior:'instant'});$(`[data-pack="${pack}"]`).focus({preventScroll:true})}
 if(b.dataset.page)navigate(b.dataset.page);
 if(b.dataset.scroll)$('#'+b.dataset.scroll)?.scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'});
 if(b.dataset.family!==undefined)updateFamily(Number(b.dataset.family));
 if(b.dataset.need){draft.family=b.dataset.need;step=0;done=false;navigate('quote')}
 if(b.dataset.stage!==undefined)updateDrop(Number(b.dataset.stage));
 if(b.dataset.cut!==undefined){cut=b.dataset.cut==='true';updateDrop(dropStep,true)}
 if(b.hasAttribute('data-sync')){scrollSync=!scrollSync;b.setAttribute('aria-pressed',scrollSync);b.textContent=`Progression au scroll : ${scrollSync?'activée':'en pause'}`;onScroll()}
 if(b.id==='motion'){saveDraft();reduced=!reduced;render()}
 if(b.id==='open-spec'||b.hasAttribute('data-open-spec'))openSpec();
 if(b.id==='close-spec')dialog.close();
 if(b.hasAttribute('data-prev')){saveDraft();step=Math.max(0,step-1);render();focusForm()}
 if(b.hasAttribute('data-reset')){Object.assign(draft,{family:'Dropout — air comprimé',application:'',pressure:'',flow:'',unknown:false,name:'',company:'',email:''});step=0;done=false;render();focusForm()}
 if(b.hasAttribute('data-sample-choice'))b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true');
 if(b.hasAttribute('data-spec-quote')){dialog.close();navigate('quote')}
 if(b.hasAttribute('data-spec-home')){dialog.close();navigate('home')}
});
document.addEventListener('input',e=>{if(!e.target.closest('form')||!e.target.name)return;saveDraft();if($('#live-summary'))$('#live-summary').innerHTML=summary(true)});
document.addEventListener('change',e=>{if(e.target.name==='unknown'){$('#pressure').disabled=e.target.checked;$('#flow').disabled=e.target.checked;saveDraft();if($('#live-summary'))$('#live-summary').innerHTML=summary(true)}});
document.addEventListener('submit',e=>{if(!e.target.matches('.form-card'))return;e.preventDefault();saveDraft();if(step<2)step++;else done=true;render();focusForm()});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
window.addEventListener('hashchange',()=>{saveDraft();matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{saveDraft();reduced=e.matches;render()});
readRoute();render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})});
let scheduled=false;function onScroll(){if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;const feature=$('[data-feature]');if(feature&&pack==='E'){const r=feature.getBoundingClientRect();feature.style.setProperty('--feature-phase',Math.max(0,Math.min(1,(innerHeight-r.top)/(innerHeight*.7))))}const cinematic=$('.cinematic');if(cinematic&&!reduced&&innerWidth>800&&innerHeight>780){const r=cinematic.getBoundingClientRect();const progress=Math.max(0,Math.min(1,-r.top/(cinematic.offsetHeight-innerHeight)));$('.scroll-track span').style.width=progress*100+'%';if(scrollSync){const next=Math.min(3,Math.floor(progress*4));if(next!==dropStep){cut=next>0;updateDrop(next,true)}}}})}
window.addEventListener('scroll',onScroll,{passive:true});
const cursor=$('.cursor');document.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||reduced||dialog.open||page==='quote'||e.target.closest('input,textarea,select,.lab-shell')){cursor.classList.remove('visible');return}cursor.classList.add('visible');cursor.style.left=e.clientX+'px';cursor.style.top=e.clientY+'px';const interactive=e.target.closest('[data-art],.family-card,.feature-object');cursor.classList.toggle('explore',!!interactive);$('span',cursor).textContent=interactive?(pack==='C'?'EXPLORER':pack==='D'?'MESURE':'VOIR'):'';const art=e.target.closest('[data-art]');if(art){const r=art.getBoundingClientRect();art.style.setProperty('--mx',((e.clientX-r.left)/r.width-.5)*10+'px');art.style.setProperty('--my',((e.clientY-r.top)/r.height-.5)*8+'px')}});document.addEventListener('pointerleave',()=>cursor.classList.remove('visible'));
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{saveDraft();reduced=e.matches;render()});
readRoute();render();
